function MillSailClothReelMaker.init() MillSailClothReelMaker.ironStock=12; MillSailClothReelMaker.bronzeStock=10; MillSailClothReelMaker.woodStock=16; MillSailClothReelMaker.leatherStock=10; MillSailClothReelMaker.silverStock=8; MillSailClothReelMaker.goldStock=6; MillSailClothReelMaker.jewelStock=4; MillSailClothReelMaker.pearlStock=4; MillSailClothReelMaker.productStock={}; MillSailClothReelMaker.buildings={}; MillSailClothReelMaker.maker=nil; MillSailClothReelMaker.activeMaking={}; MillSailClothReelMaker.totalProducts=0; MillSailClothReelMaker.dayTimer=0; print("[MillSailClothReelMaker] Royal Mill Sail Cloth Reel Maker System initialized (6 products, 4 buildings)") end
function MillSailClothReelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillSailClothReelMaker.maker={name=n or ("Vitičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitičar najet: %s (spretnost: %d)",MillSailClothReelMaker.maker.name,s),"success") end; return true end
function MillSailClothReelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillSailClothReelMaker.build(id) local ok,e=MillSailClothReelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillSailClothReelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillSailClothReelMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillSailClothReelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillSailClothReelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillSailClothReelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillSailClothReelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillSailClothReelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillSailClothReelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillSailClothReelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillSailClothReelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillSailClothReelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillSailClothReelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillSailClothReelMaker.buildings==0 then return false,"Potrebna vitična delavnica" end; if not MillSailClothReelMaker.maker then return false,"Potreben viticar" end; return true end
function MillSailClothReelMaker.make(pt,qty) qty=qty or 1; local ok,e=MillSailClothReelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillSailClothReelMaker.ironStock=MillSailClothReelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillSailClothReelMaker.bronzeStock=MillSailClothReelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillSailClothReelMaker.woodStock=MillSailClothReelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillSailClothReelMaker.leatherStock=MillSailClothReelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillSailClothReelMaker.silverStock=MillSailClothReelMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillSailClothReelMaker.goldStock=MillSailClothReelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillSailClothReelMaker.jewelStock=MillSailClothReelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillSailClothReelMaker.pearlStock=MillSailClothReelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillSailClothReelMaker.maker then t=math.max(1,t-math.floor(MillSailClothReelMaker.maker.skill/13)) end; table.insert(MillSailClothReelMaker.activeMaking,{id="millsailclothreel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillSailClothReelMaker.completeMaking(m) local q=1.0+(MillSailClothReelMaker.getQualityBonus()/100); if MillSailClothReelMaker.maker then q=q+(MillSailClothReelMaker.maker.skill/140) end; q=math.min(2.5,q); MillSailClothReelMaker.productStock[m.productType]=(MillSailClothReelMaker.productStock[m.productType] or 0)+m.quantity; MillSailClothReelMaker.totalProducts=MillSailClothReelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillSailClothReelMaker.maker then MillSailClothReelMaker.maker.itemsMade=MillSailClothReelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillSailClothReelMaker.maker.skill=math.min(100,MillSailClothReelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vitica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millsailclothreel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillSailClothReelMaker.update(dt) if not _G.state then return end; MillSailClothReelMaker.dayTimer=MillSailClothReelMaker.dayTimer+dt; if MillSailClothReelMaker.dayTimer>=30 then MillSailClothReelMaker.dayTimer=0; for i=#MillSailClothReelMaker.activeMaking,1,-1 do local m=MillSailClothReelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillSailClothReelMaker.completeMaking(m); table.remove(MillSailClothReelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillSailClothReelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillSailClothReelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillSailClothReelMaker.getStats() return {ironStock=MillSailClothReelMaker.ironStock,bronzeStock=MillSailClothReelMaker.bronzeStock,woodStock=MillSailClothReelMaker.woodStock,leatherStock=MillSailClothReelMaker.leatherStock,silverStock=MillSailClothReelMaker.silverStock,goldStock=MillSailClothReelMaker.goldStock,jewelStock=MillSailClothReelMaker.jewelStock,pearlStock=MillSailClothReelMaker.pearlStock,productStock=MillSailClothReelMaker.productStock,numBuildings=#MillSailClothReelMaker.buildings,hasMaker=MillSailClothReelMaker.maker~=nil,makerName=MillSailClothReelMaker.maker and MillSailClothReelMaker.maker.name or "—",makerSkill=MillSailClothReelMaker.maker and MillSailClothReelMaker.maker.skill or 0,activeMaking=#MillSailClothReelMaker.activeMaking,totalProducts=MillSailClothReelMaker.totalProducts} end
